func TestCleanCmd_All_ForceDeletesV2GenerationWithMatchingOID(t *testing.T) {
	repo, _ := setupCleanTestRepo(t)
	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}
	repoRoot := wt.Filesystem.Root()
	writeCleanSettingsFile(t, repoRoot, `{"enabled": true, "strategy_options": {"checkpoints_v2": true, "full_transcript_generation_retention_days": 14}}`)
	createArchivedGenerationRef(t, repo, "0000000000001", time.Now().AddDate(0, 0, -30), time.Now().AddDate(0, 0, -20))

	cmd := newCleanCmd()
	var stdout, stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	cmd.SetArgs([]string{"--all", "--force"})

	if err := cmd.Execute(); err != nil {
		t.Fatalf("clean --all --force error = %v", err)
	}

	// The ref should be deleted (OID matched via CAS)
	if _, err := repo.Reference(plumbing.ReferenceName(paths.V2FullRefPrefix+"0000000000001"), true); err == nil {
		t.Fatal("expected archived generation ref to be deleted via CAS")
	}
}

